namespace OpenTPW;

/// <summary>
/// The roller coaster slice's approximation register (docs/COASTERS.md; docs/reverse/COAST-plan.md §10). Each entry
/// is tagged <c>[APPROX:COAST-NNN]</c> at its code site. The IDs below 015 are the unknowns of the plan's §10 table that
/// COAST-R2 left open (§10.1), COAST-015..019 the new unknowns of §10.1, and COAST-024..031 rules OpenTPW had to choose
/// while implementing the plan, COAST-032 the arithmetic precision COAST-V2 found unported, and COAST-026 and COAST-033..035 what the
/// presentation (track mesh, pylons, cars, build cursor) still approximates after it was traced from tp.exe. COAST-001, 002, 003, 005, 006, 009 and 010 were resolved by COAST-R2, COAST-008 by the PPC differential
/// oracle (ORACLE.md F7: the stale term is Fz), COAST-013 (the sickness has no guest consumer: tp.exe 0x4e0560 discards it) by the COAST register round of October 14, COAST-020 (cost rates) and COAST-021 (force term) by COAST-V, and COAST-012 (the controller states and the tool's entry and exit) and COAST-019 (the closing pair of the sampler) by the three-node station round of October 15, and COAST-022 (the train layout, the hop queue, the placement by the release time) and COAST-023 (the seat types, COAST 6's bounds, the ring sizes) by the coaster train round of October 15; they are traced. COAST-004 and COAST-029 were narrowed by it, COAST-014, 015, 024 and 030 lost their station clauses.
/// </summary>
public static class CoasterApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("COAST-004", "COAST-COLLIDE: the self-intersection pass (CoasterCollision: 0x439ab0 → 0x439c40 → 0x43a2b0) runs once over the finished track instead of incrementally per edit, carries the x87 intermediates in double, takes only the default asTrackCollisionPoints (no PC .sam names them; the key layout is not decoded) and does not re-test a node marked by another node's overflowed list; there is no terrain or scenery collision in the original and fCollisionPossibleRadius is the pass's box margin; the consumers of the nodes' collision lists (+0xb0/+0xb4, flag 0x400000 at 0x4376cc) are not traced"),
		("COAST-011", "COAST-CAMERA: the ride view is the front car's pose; no camera mode uses it yet"),
		("COAST-014", "COAST-WINDOWS: the PC twins agree with the Mac readings for the rating step and final, COAST 2-6, the mode and speed setters, the guest predicates, the debit, the validator, the sampler and the hop; differences: COAST 6's 0 floor, the round-to-nearest sine-table indices of the PC (the swing follows them, the Mac-derived tables truncate) and x87 arithmetic; the cost 0x447830 is not compared"),
		("COAST-015", "COAST-TAGS: the knot pass poses each pylon model with its clips and takes the node's knots from the posed track tags of its table (0x430ed0, 0x4344c0, 0x4321c0; the stack pass 0x432d50 gives a stack's lower nodes the 0x100 mark and, on a model with two tables, the three-tag one) and the station end node's knot from S0's posed track dummy; approximated: without the pylon model (no game data) every node is one knot at its position along its tangent and the pylon heights are fMinHeight and fMaxHeight, and the clamped height parameter is not written back to the node (0x430ca0), so a parameter outside [0, 1] keeps standing the node at its raw height"),
		("COAST-017", "COAST-ROLL: sample roll interpolates the knot rolls instead of the second rail's roll plus the lerp of the nodes' tag rolls (0x43e6b0); the second rail is +(0, 1, 0) at non-loop knots and 2 × the tag's up axis on loop pylons; the tag rolls are on the knots (CoasterKnot.TagRoll), the second rail is not built"),
		("COAST-024", "COAST-INCOMPLETE: guests do not join or board a coaster that is not complete (the station counts as closed to them) or crosses itself (controller +0x140 == 0, CoasterRide.AcceptsGuests); the not-the-coaster-being-edited test of 0x441970 is not modelled itself (the coaster tool closes the ride and puts the controller in state 2, COAST-012, so an edited coaster whose track still runs drains its queue one head per turn with no thought 13, where tp.exe's 0x441970 fails for it and every guest at an unchanged place leaves with thought 13); while the coaster refuses guests its admission calls nobody forward, where tp.exe's admission 0x4e1220 does not test 0x441970 (the queue state 11 thought-13 exit 0x500612 is modelled)"),
		("COAST-026", "COAST-RENDER: the track mesh is the traced extrusion of the coaster.sam cross sections with the track textures, but it draws both faces, emits per-segment vertices, takes cross-section changes per segment (no dry/wet blend sections), shows an invalid segment as flat red and lights self-illuminated textures; scrolling textures shift V by the power factor × elapsed time as the original does, another reader of the stored scroll rate is not excluded; the coaster MD2 models' Add-mode vertex and UV animation (the TrackMaster loader 0x42fad0 keeps header flag 4, add paths of 0x471860) is not modelled (formerly the remainder of RIDES-043)"),
		("COAST-028", "COAST-TOOL: the panel of nine buttons, their enable mask, the press/drag/release handlers (height 0x441a00, rotate 0x441e80, tilt 0x442010/0x441cd0, move 0x443340/0x445a70, stack swaps 0x4423f0/0x4425c0, demolish 0x446740) and the drag rates are the original's; approximated: the drag counts the pointer in 1024-pixel units and turns the tilt drag by OpenTPW's camera heading, a pylon is picked by its cell (a stack by the nearest projected piece) where the original picks the pylon model under the pointer, the placement area's cell test is OpenTPW's occupancy for the original's cell and object types, without the pylon model (no game data) the hand-set yaw and incline turn the knot direction by a guessed angle, the panel appears at once instead of sliding out at a window position measured from the video, the pylon capabilities come from the models' clips (a generic coaster takes the defaults), the loop button's hiding rule is the coaster's loop pylon; Backspace deleting the last pylon is an extension ([EXT:coaster-tool-controls]); the coaster click refuses no pylon for money"),
		("COAST-029", "COAST-STATION: the station is the original's three nodes at the model's dummies (a StdPylon in the cell beyond '<', a pylon-less node on the middle dummy, a StdPylon beyond '>', the end node on the first one's knot); a station whose dummies lie below the StdPylon's h0 (Ghosta Coasta, Scatty Batty, Candy Coaster) stands on pylons raised to h0 as the original's knot pass clamps them (0x430ca0); what is not traced: the rating pass re-derives the platform's winch marks"),
		("COAST-030", "COAST-RULES: closing needs two pylons and validates the closing link and arrival turn by OpenTPW's rule (the original re-validates the open start of a reopened circuit and closes a fresh one by completion; a click on the station's own cells closes too, an OpenTPW convenience); edits and cuts wait for an empty train (OpenTPW's guard); the cut ends carry the markers 0x10000/0x20000 but the turn test the original skips for them in move mode (0x4348af..0x4348d8) is not skipped"),
		("COAST-032", "COAST-PRECISION: the arithmetic precision differs, the PC twins (chord 0x432840, knot norms and node tangents 0x430ed0/0x431660, the swing 0x43c450) run in x87 with extended intermediates and single or double rounded copies; C# rounds every step to single (the swing and the prism test carry double and round at the original's stores); the FPU control word at run time is not captured"),
		("COAST-033", "COAST-PYLON: pylons are their MD2 posed with all five clips in add mode (loft, rotate, incline, bank, loop tilt) at the knot pass's node values through the pylon control's clip maps, the suspended pylon's half turn (kept by straight and loop-pylon nodes from their last curve pass) and the stack parts shown or hidden by the pylon's place in its stack (0x432df0); approximated: the bottom pylon's model shadow (model +0x2c at the ground height, 0x469940) is not drawn, a part's flag hides only its own mesh, the half turn is stored only by the controller's rebuild of a finished track where the original's every edit-step rebuild (0x435d50 → 0x444700) stores it, and the clip sampler's slerp takes exact sines where 0x4742a0 reads the runtime table"),
		("COAST-034", "COAST-CAR: cars stand on the curve at their coordinate's knot-pair parameter around the train's middle car, spaced by their types' pair distances, with the model's +Z along the track; they are drawn as the static rest mesh: the bend of bBendCar types (fBendElevationLow/High, 0x438800) and the model clip played at the type's speed factor × the train speed (0x474050) are not reproduced, and the mine cart's camera seat is turned to look along the track; a rider hangs on the socket of its index in the car's seated list, the PC's socket order (0x44b270)"),
		("COAST-035", "COAST-GHOST: the build cursor links a spare node (flag 0x8000, plus 0x4000 when the validator refuses the cell) after the last node and the track is drawn through it, without a pylon, as a translucent ribbon, blue or red; the ribbon's mesh (6 units wide) and colours are OpenTPW's, the original's renderer consumers of node flags 0x8000/0x4000 and of uiInvalidCrossSection are not found; the cursor follows every hovered cell where the original reaches 300 units from the last node; the closing target marks the chain start only through the cursor cell's colour")
	};

	private static bool logged;

	public static void LogOnce()
	{
		if ( logged )
			return;
		logged = true;
		foreach ( var (id, rule) in Entries )
			Log?.Warning( $"[APPROX:{id}] {rule}" );
	}
}
